MANIFESTS = [
    {
        "name": "orders-api",
        "labels": {"platform.io/owner": "team-orders"},
        "containers": [
            {"name": "app",  "cpu_limit": "500m", "env": [("DB_SECRET", None, "ref")]},
            {"name": "otel", "cpu_limit": "100m", "env": []},
        ],
    },
    {
        "name": "quick-hack",
        "labels": {},
        "containers": [
            {"name": "app",     "cpu_limit": "500m",
             "env": [("API_SECRET", "sk_live_abc123", "inline")]},
            {"name": "sidecar", "cpu_limit": None, "env": []},
        ],
    },
]

def evaluate(manifest):
    denies = []
    if "platform.io/owner" not in manifest["labels"]:
        denies.append(f"service '{manifest['name']}' has no platform.io/owner label")
    for c in manifest["containers"]:
        if not c["cpu_limit"]:
            denies.append(f"container '{c['name']}' is missing a CPU limit")
    for c in manifest["containers"]:
        for env_name, env_value, kind in c["env"]:
            if kind == "inline" and "secret" in env_name.lower():
                denies.append(f"container '{c['name']}' sets secret '{env_name}' inline")
    return denies

total_denies = 0
for m in MANIFESTS:
    denies = evaluate(m)
    total_denies += len(denies)
    if denies:
        print(f"{m['name']}: DENIED")
        for d in denies:
            print(f"  - {d}")
    else:
        print(f"{m['name']}: ALLOWED")
print(f"denies: {total_denies}")
print(f"gate: {'can fire' if total_denies > 0 else 'THEATER — never fired'}")

