BUNDLE = {
    "files": {
        "Dockerfile": "FROM python:3.12-slim ...",
        ".github/workflows/deliver.yml": "uses: acme-platform/.github/workflows/delivery-contract.yml@v3",
        "iac/main.tf": "module \"service_env\" { source = \"platform/service-env/aws\" }",
        "config.yaml": "db_url: postgres://orders:hunter2@db:5432/orders",
        "otel-collector.yaml": "receivers: { otlp: ... }",
    },
    "catalog": {"owner": "team-orders", "oncall": "", "runbook": "docs/runbook.md"},
}

REQUIRED_OUTPUTS = [
    ("repo",          lambda b: "Dockerfile" in b["files"]),
    ("pipeline",      lambda b: any("delivery-contract" in v for k, v in b["files"].items() if k.endswith(".yml"))),
    ("environment",   lambda b: any(k.startswith("iac/") for k in b["files"])),
    ("telemetry",     lambda b: "otel-collector.yaml" in b["files"]),
    ("owner",         lambda b: bool(b["catalog"]["owner"])),
    ("oncall",        lambda b: bool(b["catalog"]["oncall"])),
]

def secret_scan(files):
    hits = []
    for name, content in sorted(files.items()):
        for line in content.splitlines():
            low = line.lower()
            if "://" in line and "@" in line and ":" in line.split("://", 1)[1].split("@", 1)[0]:
                hits.append((name, "credential in connection string"))
            elif any(k in low for k in ("password:", "token:", "api_key:")) and "ref" not in low:
                hits.append((name, "plaintext credential value"))
    return hits

def validate(bundle):
    results = []
    for output, check in REQUIRED_OUTPUTS:
        results.append((output, check(bundle)))
    hits = secret_scan(bundle["files"])
    passed = sum(1 for _, ok in results if ok)
    verdict = "GOLDEN PATH" if passed == len(results) and not hits else "REPO GENERATOR"
    return results, hits, passed, verdict

results, hits, passed, verdict = validate(BUNDLE)
for output, ok in results:
    print(f"{output}: {'PASS' if ok else 'MISSING'}")
for name, why in hits:
    print(f"secret_scan: {name} -> {why}")
print(f"outputs: {passed}/{len(REQUIRED_OUTPUTS)}")
print(f"verdict: {verdict}")

