import base64

FILES = {
    "values.yaml": [
        "replicas: 3",
        "dbPassword: aHVudGVyMi1wcm9k",          # base64 — NOT encryption
        "image: registry/orders:1.4.2",
    ],
    "secrets.yaml": [
        "kind: ExternalSecret",
        "remoteRef: platform/orders/db",           # a NAME — safe
    ],
    "deploy.env": [
        "STRIPE_TOKEN=sk_live_9f8g7h6j5k4l",       # plaintext credential
        "LOG_LEVEL=info",
    ],
    ".git-history.bak": [
        "dbPassword: old-hunter2",                  # deleted, still in history
    ],
}

def looks_base64_secret(value):
    if len(value) < 12:
        return False
    try:
        decoded = base64.b64decode(value, validate=True).decode()
    except Exception:
        return False
    return any(c.isalpha() for c in decoded)

def scan(files):
    findings = []
    for fname in sorted(files):
        for line in files[fname]:
            stripped = line.strip()
            key = stripped.split(":")[0].split("=")[0].strip().lower()
            val = stripped.split(":", 1)[-1].split("=", 1)[-1].strip()
            sensitive = any(m in key for m in ("password", "token", "secret", "key"))
            if not sensitive:
                continue
            if "remoteref" in key.replace("_", "").lower() or val.startswith("platform/"):
                continue
            if looks_base64_secret(val):
                findings.append((fname, key, "base64-encoded credential (encoding is not encryption)"))
            elif val and not val.startswith("${"):
                findings.append((fname, key, "plaintext credential value"))
    return findings

findings = scan(FILES)
for fname, key, why in findings:
    print(f"{fname}: {key} -> {why}")
print(f"findings: {len(findings)}")
print(f"repo: {'CLEAN' if not findings else 'CREDENTIALS AT REST'}")

