INTENT = {
    "name": "checkout-api",
    "team": "payments",
    "image": "registry/checkout-api:1.4.2",
    "port": 8080,
    "replicas": {"min": 3, "max": 10},
    "healthcheck": "/healthz",
    "env": [("DATABASE_URL", "fromSecret", "checkout-db")],
}

def render(intent):
    errors = []
    if not (1 <= intent["port"] <= 65535):
        errors.append(f"port {intent['port']} out of range")
    rmin, rmax = intent["replicas"]["min"], intent["replicas"]["max"]
    if rmin < 1 or rmin > rmax:
        errors.append(f"replicas min={rmin} max={rmax} invalid")
    for name, kind, ref in intent["env"]:
        if kind != "fromSecret" and ("secret" in name.lower() or "password" in name.lower()):
            errors.append(f"env {name} must be a secret reference")
    if errors:
        return None, errors
    objects = [
        ("Deployment", f"replicas={rmin}, image={intent['image']}, "
                       f"readiness={intent['healthcheck']}, liveness={intent['healthcheck']}, "
                       f"limits=500m/512Mi (platform default)"),
        ("Service",    f"port {intent['port']} -> {intent['name']}:{intent['port']}"),
        ("HPA",        f"min={rmin} max={rmax} target=70% cpu"),
        ("ServiceMonitor", "otel sidecar + scrape config (auto-attached)"),
    ]
    return objects, errors

objects, errors = render(INTENT)
team_fields = len(INTENT)
print(f"team_declares: {team_fields} fields")
if errors:
    for e in errors:
        print(f"INVALID: {e}")
else:
    for kind, summary in objects:
        print(f"render {kind}: {summary}")
    print(f"platform_owns: {len(objects)} object kinds")
print(f"verdict: {'RENDERED' if not errors else 'REJECTED'}")

