# Ownership boundary: which failure classes belong to which side
PLATFORM_OWNS = {"template", "provisioning", "secrets-wiring", "observability-defaults"}
TEAM_OWNS = {"service-code", "service-slo", "business-config"}

# Tier SLOs in minutes (first response)
TIER_SLO = {"L2": 240, "L3": 30}

TICKETS = [
    # (id, failure_class, minutes_open, self_resolve_attempted)
    ("T-101", "template",        20,  True),   # scaffold render fails
    ("T-102", "service-code",    45,  False),  # NPE in team's handler
    ("T-103", "provisioning",    290, True),   # namespace stuck creating
    ("T-104", "secrets-wiring",  25,  False),  # vault path not bound
    ("T-105", "business-config", 12,  False),  # wrong price table
    ("T-106", "template",        44,  True),   # golden path outage, launch blocked
]

SIDE_CHANNEL_DEPLOYS_THIS_WEEK = 3
TRIPWIRE = 2

def route(ticket):
    tid, fclass, mins, attempted = ticket
    if fclass in TEAM_OWNS:
        return (tid, "REJECT->team", f"'{fclass}' is team-owned; named owner: the service team")
    if not attempted:
        return (tid, "L1", "self-serve first: template/runbook not yet attempted")
    tier = "L3" if mins > TIER_SLO["L2"] or fclass == "template" and mins > 30 else "L2"
    breach = mins > TIER_SLO[tier]
    note = f"platform-owned '{fclass}'" + (f" — SLO BREACH ({mins}m > {TIER_SLO[tier]}m)" if breach else "")
    return (tid, tier, note)

breaches = 0
for t in TICKETS:
    tid, tier, note = route(t)
    if "BREACH" in note:
        breaches += 1
    print(f"{tid}: {tier} — {note}")
print(f"slo_breaches: {breaches}")
tripped = SIDE_CHANNEL_DEPLOYS_THIS_WEEK > TRIPWIRE
print(f"bypass_tripwire: {SIDE_CHANNEL_DEPLOYS_THIS_WEEK} side-channel deploys (limit {TRIPWIRE}) -> {'TRIPPED — audit the path' if tripped else 'ok'}")

